import hashlib
import binascii


def task_func(salt, cursor):
    if not isinstance(salt, str):
        raise TypeError("salt must be a string")

    def _quote_identifier(name):
        return '"' + name.replace('"', '""') + '"'

    def _find_target_table():
        tables = cursor.execute(
            "SELECT name, sql FROM sqlite_master "
            "WHERE type='table' AND name NOT LIKE 'sqlite_%'"
        ).fetchall()

        if not tables:
            return None

        preferred = [t for t in tables if "user" in (t[0] or "").lower()]
        ordered = preferred + [t for t in tables if t not in preferred]

        for table_name, create_sql in ordered:
            info = cursor.execute(
                f"PRAGMA table_info({_quote_identifier(table_name)})"
            ).fetchall()
            if not info:
                continue

            columns = [row[1] for row in info]
            password_column = next(
                (c for c in columns if c.lower() in {"password", "passwd", "pwd"}),
                None,
            )
            if password_column is None:
                continue

            pk_columns = [row[1] for row in info if row[5]]
            without_rowid = "without rowid" in (create_sql or "").lower()

            if without_rowid and not pk_columns:
                continue

            return table_name, password_column, pk_columns, without_rowid

        return None

    target = _find_target_table()
    if target is None:
        return 0

    table_name, password_column, pk_columns, without_rowid = target

    if without_rowid:
        key_columns = pk_columns
    else:
        key_columns = []

    if not without_rowid:
        select_columns = ["rowid", password_column]
        where_clause = "rowid = ?"
    else:
        select_columns = key_columns + [password_column]
        where_clause = " AND ".join(
            f"{_quote_identifier(col)} = ?" for col in key_columns
        )

    select_sql = (
        f"SELECT {', '.join('rowid' if col == 'rowid' else _quote_identifier(col) for col in select_columns)} "
        f"FROM {_quote_identifier(table_name)}"
    )
    rows = cursor.execute(select_sql).fetchall()

    updated = 0
    for row in rows:
        if without_rowid:
            key_values = row[:-1]
            password = row[-1]
        else:
            key_values = (row[0],)
            password = row[1]

        if password is None:
            continue

        if isinstance(password, bytes):
            password_text = password.decode("utf-8")
        else:
            password_text = str(password)

        hashed_password = hashlib.sha256((salt + password_text).encode("utf-8")).hexdigest()

        cursor.execute(
            f"UPDATE {_quote_identifier(table_name)} "
            f"SET {_quote_identifier(password_column)} = ? "
            f"WHERE {where_clause}",
            (hashed_password, *key_values),
        )
        updated += 1

    return updated
